using System;
using System.IO;
using System.Text;
using System.Linq;
using System.Collections.Generic;
public static class SelfTests {
 static int assertions;
 static void Assert(bool value,string message){assertions++;if(!value)throw new Exception(message);}
 static void Reject(Action action,string message){bool rejected=false;try{action();}catch{rejected=true;}Assert(rejected,message);}
 public static int Run(){var test=Path.Combine(Path.GetTempPath(),"UBWThai-fixture-"+Guid.NewGuid().ToString("N"));try{Directory.CreateDirectory(test);var steam=Path.Combine(test,"steamapps");var root=Path.Combine(steam,@"common\StarshipTroopers_UltimateBugWar");var paks=Path.Combine(root,@"StarshipTroopers_UBW\Content\Paks");Directory.CreateDirectory(paks);File.WriteAllText(Path.Combine(root,"StarshipTroopers_UBW.exe"),"fixture");File.WriteAllText(Path.Combine(steam,"appmanifest_2321780.acf"),"\"appid\" \"2321780\" \"buildid\" \"22832378\"");var basePak=Path.Combine(paks,"pakchunk0-Windows.pak");var baseToc=Path.Combine(paks,"pakchunk0-Windows.utoc");File.WriteAllText(basePak,"base-pak");File.WriteAllText(baseToc,"base-toc");var p=new Policy{PakHash=Engine.HashFile(basePak),TocHash=Engine.HashFile(baseToc),LegacyHash=Engine.Hash(Encoding.UTF8.GetBytes("legacy"))};foreach(var ext in new[]{"pak","utoc","ucas"})p.Payload["UBW-Thai-UI-pilot_P."+ext]=Encoding.UTF8.GetBytes("new-"+ext);p.FixtureRoot=root;var e=new Engine(root,p);var mods=Path.Combine(paks,"~mods");e.Check(true);Assert(!Directory.Exists(mods),"check must not write");
  var reshade=Path.Combine(root,@"StarshipTroopers_UBW\Binaries\Win64\dxgi.dll");Directory.CreateDirectory(Path.GetDirectoryName(reshade));File.WriteAllText(reshade,"ReShade fixture");
  e.Change(false);foreach(var x in p.Payload)Assert(Engine.HashFile(Path.Combine(mods,x.Key))==Engine.Hash(x.Value),"fresh install");e.Change(false);Assert(File.Exists(Path.Combine(mods,"UBWThai-install.json")),"repeat install receipt");e.Change(true);Assert(p.Payload.Keys.All(x=>!File.Exists(Path.Combine(mods,x))),"restore only owned files");Assert(File.ReadAllText(reshade)=="ReShade fixture"&&Engine.HashFile(basePak)==p.PakHash,"base/ReShade untouched");
  // Unknown same-name files must survive failed operations.
  var target=Path.Combine(mods,"UBW-Thai-UI-pilot_P.pak");File.WriteAllText(target,"foreign");Reject(()=>e.Change(false),"unknown replacement blocked");Assert(File.ReadAllText(target)=="foreign","unknown retained");Reject(()=>e.Change(true),"unknown deletion blocked");File.Delete(target);
  // Supported baseline migration and rollback after mid-transaction failure.
  File.WriteAllText(target,"legacy");foreach(var x in p.Payload.Where(x=>!x.Key.EndsWith(".pak")))File.WriteAllBytes(Path.Combine(mods,x.Key),x.Value);e.Fault=i=>{if(i==2)throw new Exception("simulated write failure");};Reject(()=>e.Change(false),"injected failure");Assert(File.ReadAllText(target)=="legacy","migration rollback preserved baseline");Assert(!File.Exists(Path.Combine(mods,"UBWThai-pending.json")),"rollback journal cleaned");e.Fault=null;e.Change(false);Assert(Engine.HashFile(target)==Engine.Hash(p.Payload[Path.GetFileName(target)]),"migration installed");
  e.Fault=i=>{if(i==2)throw new Exception("simulated removal failure");};Reject(()=>e.Change(true),"removal failure");Assert(p.Payload.All(x=>File.Exists(Path.Combine(mods,x.Key))&&Engine.HashFile(Path.Combine(mods,x.Key))==Engine.Hash(x.Value)),"removal rollback");e.Fault=null;
  File.WriteAllText(basePak,"changed-build");Reject(()=>e.Change(false),"changed base blocked");e.Change(true);Assert(!File.Exists(target),"restore permitted after base change");
  // Simulate a terminated process with a durable pending journal.
  var pending=new Journal{Root=root,Phase="pending",Before=p.Payload.Keys.ToDictionary(x=>x,x=>(string)null),ReceiptBefore=null};var jp=Path.Combine(mods,"UBWThai-pending.json");File.WriteAllBytes(target,p.Payload[Path.GetFileName(target)]);File.WriteAllText(jp,new System.Web.Script.Serialization.JavaScriptSerializer().Serialize(pending));e.Recover();Assert(!File.Exists(target)&&!File.Exists(jp),"interrupted fresh install recovered");
  File.WriteAllBytes(target,p.Payload[Path.GetFileName(target)]);pending.Phase="committed";File.WriteAllText(jp,new System.Web.Script.Serialization.JavaScriptSerializer().Serialize(pending));e.Recover();Assert(File.Exists(target)&&!File.Exists(jp),"committed install retained");File.Delete(target);
  File.WriteAllText(basePak,"base-pak");File.WriteAllText(Path.Combine(steam,"appmanifest_2321780.acf"),"\"appid\" \"2321780\" \"buildid\" \"other\"");Reject(()=>e.Change(false),"new build blocked");
  File.WriteAllText(Path.Combine(steam,"appmanifest_2321780.acf"),"\"appid\" \"2321780\" \"buildid\" \"22832378\"");e.Change(false);File.AppendAllText(target,"tamper");Reject(()=>e.Change(true),"changed mod blocked");Assert(File.ReadAllText(target).EndsWith("tamper"),"changed mod preserved");
  // Embedded distribution assets and licenses must be complete.
  var pub=Policy.Public();Assert(pub.Payload.Count==3,"three embedded files");foreach(var ext in new[]{"pak","utoc","ucas"})Assert(pub.Payload["UBW-Thai-UI-pilot_P."+ext].Length>0,"payload nonempty");foreach(var name in new[]{"Orbitron-OFL","Oxanium-OFL","Noto-OFL","NotoThai-OFL"})Assert(Resources.Text(name).Contains("SIL OPEN FONT LICENSE"),"embedded OFL");Assert(Resources.Text("Credits").Contains("AI"),"credits embedded");
  File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"installer-test-result.json"),"{\"passed\":true,\"assertions\":"+assertions+",\"game_modified\":false,\"fixtures_only\":true}");return 0;
 }catch(Exception ex){File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"installer-test-result.json"),"{\"passed\":false,\"error\":\""+ex.ToString().Replace("\\","\\\\").Replace("\"","\\\"").Replace("\r"," ").Replace("\n"," ")+"\"}");return 1;}finally{var full=Path.GetFullPath(test);if(full.StartsWith(Path.GetFullPath(Path.GetTempPath()),StringComparison.OrdinalIgnoreCase)&&Path.GetFileName(full).StartsWith("UBWThai-fixture-"))Directory.Delete(full,true);}}
}
